import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import CommentPost from 'flarum/forum/components/CommentPost';
import UserPage from 'flarum/forum/components/UserPage';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import DiscussionPage from 'flarum/forum/components/DiscussionPage';
import LinkButton from 'flarum/common/components/LinkButton';
import abbreviateNumber from 'flarum/common/utils/abbreviateNumber';
import Icon from 'flarum/common/components/Icon';
import { flush, guestProfile, guestRead, listen } from './tracker';
import { settingsItems } from './settings';
const t = (key, params) => app.translator.trans('ernestdefoe-vantage.forum.' + key, params);
app.initializers.add('ernestdefoe/vantage', () => {
  // 🚨 The dashboard is its own chunk: nothing in it loads on other pages.
  app.routes['user.vantage'] = {
    path: '/u/:username/stats',
    component: () => import(/* webpackChunkName: 'forum/components/StatsPage', webpackMode: 'lazy-once' */ './components/StatsPage')
  };

  // The free number: views under each post, from the payload the page already has.
  extend(CommentPost.prototype, 'footerItems', function (items) {
    const views = this.attrs.post.attribute('vantageViews');
    if (typeof views !== 'number' || views < 1) return;
    items.add('vantageViews', m('span.VantageViews', {
      title: t('post_views', {
        count: views
      })
    }, [m(Icon, {
      name: 'far fa-eye'
    }), ' ', abbreviateNumber(views)]), -20);
  });
  const canSee = user => {
    if (!user || !app.session.user) return false;
    return user === app.session.user ? true : !!app.forum.attribute('vantageCanViewOthers');
  };
  extend(UserPage.prototype, 'navItems', function (items) {
    if (!canSee(this.user)) return;
    items.add('vantage', LinkButton.component({
      href: app.route('user.vantage', {
        username: this.user.slug()
      }),
      icon: 'fas fa-chart-line'
    }, t('nav')), 70);
  });
  extend(SessionDropdown.prototype, 'items', function (items) {
    const user = app.session.user;
    if (!user || !app.forum.attribute('vantageCanView')) return;
    items.add('vantage', LinkButton.component({
      href: app.route('user.vantage', {
        username: user.slug()
      }),
      icon: 'fas fa-chart-line'
    }, t('session_item')), 90);
  });

  // Guests: the posts that scrolled past, sent once when they leave.
  extend(DiscussionPage.prototype, 'positionChanged', function (_r, start, end) {
    const id = this.discussion?.id?.();
    if (id) guestRead(Number(id), start, end);
  });
  extend(DiscussionPage.prototype, 'onremove', () => flush());
  extend(UserPage.prototype, 'show', function (_r, user) {
    if (user?.id?.()) guestProfile(user.id());
  });

  // SettingsPage is a lazy chunk in Flarum 2, so it is extended by path.
  extend('flarum/forum/components/SettingsPage', 'settingsItems', function (items) {
    settingsItems(items);
  });
  listen();
});flarum.reg.addChunkModule('ernestdefoe-vantage:forum/components/StatsPage', '836', 'ernestdefoe-vantage', 'forum/components/StatsPage');
flarum.reg.addChunkModule('ernestdefoe-vantage:forum/components/StatsPage', '836', 'ernestdefoe-vantage', 'forum/components/Dashboard');
flarum.reg.addChunkModule('ernestdefoe-vantage:forum/components/StatsPage', '836', 'ernestdefoe-vantage', 'forum/components/LineChart');