import app from 'flarum/forum/app';
import FieldSet from 'flarum/common/components/FieldSet';
import Switch from 'flarum/common/components/Switch';
import Select from 'flarum/common/components/Select';
const t = key => app.translator.trans('ernestdefoe-vantage.forum.settings.' + key);

/** Settings → "Stats and privacy": the reader's own choices. */
export function settingsItems(items) {
  const user = app.session.user;
  if (!user) return;
  const prefs = user.preferences() || {};
  const save = (key, value) => user.savePreferences({
    [key]: value
  }).then(() => m.redraw());
  const demographics = !!app.forum.attribute('vantageDemographics');
  const years = {
    '': t('gender_none')
  };
  const now = new Date().getFullYear();
  for (let y = now - 13; y >= now - 100; y--) years[String(y)] = String(y);
  items.add('vantage', m(FieldSet, {
    className: "Settings-vantage",
    label: t('title')
  }, m(Switch, {
    state: !!prefs.vantageNoCount,
    onchange: v => save('vantageNoCount', v)
  }, t('no_count')), demographics && [m(Switch, {
    state: !!prefs.vantageShareAudience,
    onchange: v => save('vantageShareAudience', v)
  }, t('share_audience')), prefs.vantageShareAudience && m("div", {
    className: "Settings-vantageFields"
  }, m("label", null, m("span", null, t('birth_year')), m(Select, {
    value: prefs.vantageBirthYear ? String(prefs.vantageBirthYear) : '',
    options: years,
    onchange: v => save('vantageBirthYear', v ? Number(v) : null)
  })), m("label", null, m("span", null, t('gender')), m(Select, {
    value: prefs.vantageGender || '',
    options: {
      '': t('gender_none'),
      woman: app.translator.trans('ernestdefoe-vantage.forum.audience.genders_list.woman'),
      man: app.translator.trans('ernestdefoe-vantage.forum.audience.genders_list.man'),
      nonbinary: app.translator.trans('ernestdefoe-vantage.forum.audience.genders_list.nonbinary')
    },
    onchange: v => save('vantageGender', v || null)
  })))]), -6);
}